// types/ai.ts

/**
 * ARTIFICIAL INTELLIGENCE TYPES
 *
 * This file contains the types related to EcoShop's AI features,
 * including image analysis (EcoScan) and the sustainability chat.
 *
 * The AI uses two providers:
 * - Azure Custom Vision: image classification (identifies materials)
 * - Google Gemini 2.0 Flash: text generation (analysis, chat)
 */

/**
 * Complete analysis generated by the AI for a recyclable material.
 * Returned by Gemini based on the prompt in lib/ai/prompts/sustainability.ts
 *
 * ALL fields are required strings (minimum 1 character)
 * so the frontend always has content to display.
 */
export interface AiAnalysis {
  /**
   * Environmental impact of the material.
   * Includes consequences for fauna/flora and statistical data on production
   * and incorrect disposal. E.g.: "Plastic production emits 1.8 tonnes of CO₂..."
   */
  environmental_impact: string;

  /**
   * Estimated decomposition time in nature.
   * Includes factors that affect decomposition (temperature, humidity)
   * and a comparison with other materials.
   * E.g.: "PET bottle: 400+ years. Styrofoam: never fully decomposes."
   */
  decomposition_time: string;

  /**
   * Detailed instructions for correct disposal.
   * Includes the bin color (selective collection), preparation (cleaning, crushing),
   * alternative locations (drop-off points, cooperatives) and what NOT to do.
   * E.g.: "Plastic → red bin. Rinse before discarding."
   */
  disposal_instructions: string;

  /**
   * Assessment of the material's recyclability.
   * Includes the level (High/Medium/Low), recycling percentages in Brazil/the world,
   * a summarized process and technical limitations.
   * E.g.: "Glass: HIGH recyclability. In Brazil, 47% is recycled."
   */
  recyclability: string;

  /**
   * Practical tips for reduction, reuse and sustainable alternatives.
   * 4 to 5 actionable tips for the user to apply day to day.
   * E.g.: "Prefer reusable bottles. Avoid plastic straws."
   */
  sustainable_tips: string;

  /**
   * Environmental benefits of recycling this specific material.
   * Includes resource savings (with numbers when possible),
   * CO₂ emission reduction and job creation in the chain.
   * E.g.: "Recycling 1 tonne of paper saves 17 trees."
   */
  recycling_benefits: string;
}

/**
 * Complete result of the scan operation (image analysis).
 * It can represent SUCCESS (identification with confidence ≥ threshold)
 * or FAILURE (low confidence, unrecognized material, provider error).
 *
 * Uses a discriminated union via the 'success' field:
 * - success: true → material, confidence, sustainability_analysis present
 * - success: false → message, suggestion, required_minimum_confidence present
 */
export interface ScanResult {
  /** Indicates whether the analysis succeeded (confidence ≥ configured threshold) */
  success: boolean;

  // --- SUCCESS FIELDS (success = true) ---
  /** Material identified by the AI (e.g. "plastico", "vidro", "papelao") */
  material?: string;
  /** Classification confidence (0 to 100) — actual percentage value */
  confidence?: number;
  /** Unique ID generated for this analysis (format: analysis_{timestamp}_{random}) */
  imageId?: string;
  /** Detailed sustainability analysis generated by Gemini */
  sustainability_analysis?: AiAnalysis;

  // --- FAILURE FIELDS (success = false) ---
  /** Friendly message explaining the reason for the failure */
  message?: string;
  /** Tip for the user to improve the photo (lighting, proximity) */
  suggestion?: string;
  /** Minimum confidence required to consider an identification valid (percentage value) */
  required_minimum_confidence?: number;
  /** Material with the highest probability (even below the threshold) */
  probable_material?: string;

  // --- COMMON FIELDS (always present) ---
  /** ISO 8601 timestamp of the analysis (e.g. "2026-05-18T10:30:00.000Z") */
  timestamp: string;
}

/**
 * Single message in the AI chat history.
 * Follows the format expected by the Google Gemini API.
 */
export interface ChatMessage {
  /** Message sender: 'user' for the user, 'model' for the AI */
  role: "user" | "model";
  /** Array of message parts (currently only one with text) */
  parts: { text: string }[];
}

/**
 * Request body for the POST /api/ai/chat endpoint
 * Sends the user's message and the conversation history to keep context.
 */
export interface ChatBody {
  /** Current user message (minimum 1 character, maximum 2000) */
  message: string;
  /**
   * Conversation history (optional).
   * Lets the AI stay coherent in multi-turn conversations.
   * Example: [{ role: "user", parts: [{ text: "What is recycling?" }] },
   *           { role: "model", parts: [{ text: "Recycling is..." }] }]
   */
  history?: ChatMessage[];
}

/**
 * Response of the POST /api/ai/chat endpoint
 * Returns only the text generated by the AI (no metadata, to keep it simple).
 */
export interface ChatResponse {
  /** Text of the response generated by the Gemini model */
  answer: string;
}

/**
 * Alias for ScanResult kept for compatibility with legacy code.
 * ScanResponse is the type returned by the POST /api/ai/scan endpoint
 */
export interface ScanResponse extends ScanResult {}
